$uid=(int)$_SESSION['user_id'];$school=filter_var($_POST['school_id']??null,FILTER_VALIDATE_INT);$file=$_FILES['pupil_csv']??null;if(!$school||!$file||!is_array($file)||($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_uploaded_file((string)($file['tmp_name']??''))||(int)($file['size']??0)>5*1024*1024)pupil_import_json(422,['ok'=>false,'message'=>'Choose a CSV file no larger than 5 MB.']);try{$db=db();}catch(Throwable $e){error_log('Pupil import connection error: '.$e->getMessage());pupil_import_json(500,['ok'=>false,'message'=>'The pupil import service is unavailable.']);}$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())pupil_import_json(403,['ok'=>false,'message'=>'That school is outside your access.']);$handle=fopen($file['tmp_name'],'rb');if(!$handle)pupil_import_json(422,['ok'=>false,'message'=>'The CSV file could not be opened.']);$read=static fn()=>fgetcsv($handle,0,',','"','\\');$header=$read();if(!$header){fclose($handle);pupil_import_json(422,['ok'=>false,'message'=>'The CSV file is empty.']);}$header[0]=preg_replace('/^\xEF\xBB\xBF/','',(string)$header[0]);$aliases=['admission number'=>'admission_number','full names'=>'full_names','first name'=>'first_name','middle name'=>'middle_name','last name'=>'last_name','class level'=>'class_level','stream'=>'stream','dob'=>'date_of_birth','date of birth'=>'date_of_birth','day or boarding'=>'scholar_type','scholar type'=>'scholar_type','parent/guardian name'=>'guardian_name','guardian name'=>'guardian_name','guardian phone number'=>'guardian_phone','guardian phone'=>'guardian_phone'];$columns=[];foreach($header as $col){$key=mb_strtolower(trim((string)$col));if(!isset($aliases[$key])){fclose($handle);pupil_import_json(422,['ok'=>false,'message'=>'Unrecognized CSV column: '.trim((string)$col)]);}$columns[]=$aliases[$key];}if(count($columns)!==count(array_unique($columns))||!in_array('admission_number',$columns,true)||!in_array('class_level',$columns,true)||(!in_array('full_names',$columns,true)&&(!in_array('first_name',$columns,true)||!in_array('last_name',$columns,true)))||(in_array('full_names',$columns,true)&&(in_array('first_name',$columns,true)||in_array('middle_name',$columns,true)||in_array('last_name',$columns,true)))){fclose($handle);pupil_import_json(422,['ok'=>false,'message'=>'Use the provided template or include unique admission number, class level, and pupil name columns.']);}
$q=$db->prepare('SELECT name FROM school_classes WHERE school_id=?');$q->execute([$school]);$classNames=[];foreach($q->fetchAll(PDO::FETCH_COLUMN) as $className)$classNames[mb_strtolower((string)$className)]=(string)$className;$q=$db->prepare('SELECT c.name class_name,st.name stream_name FROM school_streams st JOIN school_classes c ON c.id=st.class_id WHERE c.school_id=?');$q->execute([$school]);$streamMap=[];foreach($q->fetchAll() as $row)$streamMap[mb_strtolower($row['class_name']).'|'.mb_strtolower($row['stream_name'])]=(string)$row['stream_name'];$rows=[];$errors=[];$admissions=[];$line=1;$tooMany=false;$processed=0;while(($values=$read())!==false){$line++;if($values===[null]||count($values)===1&&trim((string)$values[0])==='')continue;if(++$processed>500){$tooMany=true;break;}if(count($values)!==count($columns)){$errors[]=['row'=>$line,'message'=>'The number of values does not match the header.'];continue;}$r=array_fill_keys(['full_names','admission_number','first_name','middle_name','last_name','date_of_birth','class_level','stream','scholar_type','guardian_name','guardian_phone'],'');foreach($columns as $i=>$key)$r[$key]=trim((string)($values[$i]??''));if($r['full_names']!==''){$parts=preg_split('/\s+/u',$r['full_names'],-1,PREG_SPLIT_NO_EMPTY);if(!$parts||count($parts)<2){$errors[]=['row'=>$line,'message'=>'Full Names must contain at least a first and last name.'];continue;}$r['first_name']=array_shift($parts);$r['last_name']=array_pop($parts);$r['middle_name']=implode(' ',$parts);}if(!$r['admission_number']||mb_strlen($r['admission_number'])>60||!$r['first_name']||mb_strlen($r['first_name'])>80||mb_strlen($r['middle_name'])>80||!$r['last_name']||mb_strlen($r['last_name'])>80||!$r['class_level']||mb_strlen($r['class_level'])>80||mb_strlen($r['stream'])>80||mb_strlen($r['guardian_name'])>140||mb_strlen($r['guardian_phone'])>30){$errors[]=['row'=>$line,'message'=>'Required admission, name, and class values are missing or a field exceeds its length limit.'];continue;}$classKey=mb_strtolower($r['class_level']);if(!isset($classNames[$classKey])){$errors[]=['row'=>$line,'message'=>'The class does not belong to this school.'];continue;}$r['class_level']=$classNames[$classKey];$streamKey=$classKey.'|'.mb_strtolower($r['stream']);if($r['stream']!==''&&!isset($streamMap[$streamKey])){$errors[]=['row'=>$line,'message'=>'The stream does not belong to the selected class.'];continue;}if($r['stream']!=='')$r['stream']=$streamMap[$streamKey];$dob=$r['date_of_birth'];if($dob!==''&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$dob)||!checkdate((int)substr($dob,5,2),(int)substr($dob,8,2),(int)substr($dob,0,4))||$dob>date('Y-m-d'))){$errors[]=['row'=>$line,'message'=>'Date of birth must be a valid date not later than today.'];continue;}$scholar=mb_strtolower($r['scholar_type']?:'day');if(!in_array($scholar,['day','boarding'],true)){$errors[]=['row'=>$line,'message'=>'Day or Boarding must be Day or Boarding.'];continue;}$r['scholar_type']=$scholar;$admissionKey=mb_strtolower($r['admission_number']);if(isset($admissions[$admissionKey])){$errors[]=['row'=>$line,'message'=>'Admission number is duplicated in this file.'];continue;}$admissions[$admissionKey]=true;$r['line']=$line;$rows[]=$r;}fclose($handle);if($tooMany)$errors[]=['row'=>$line,'message'=>'A CSV import may contain no more than 500 pupils.'];if(!$rows&& !$errors)$errors[]=['row'=>0,'message'=>'The CSV contains no pupil records.'];$existing=[];if($rows){$q=$db->prepare('SELECT admission_number FROM pupils WHERE school_id=? AND admission_number=?');foreach($rows as $r){$q->execute([$school,$r['admission_number']]);if($q->fetchColumn()!==false)$errors[]=['row'=>$r['line'],'message'=>'Admission number already exists in this school.'];}}if($errors)pupil_import_json(422,['ok'=>false,'message'=>'No pupils were imported. Correct the listed rows and upload the complete file again.','data'=>['errors'=>array_slice($errors,0,100),'errors_truncated'=>count($errors)>100]]);
try{$db->beginTransaction();$insert=$db->prepare('INSERT INTO pupils(school_id,admission_number,first_name,middle_name,last_name,date_of_birth,class_level,stream,scholar_type,guardian_name,guardian_phone) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$history=$db->prepare('INSERT INTO pupil_class_history(pupil_id,school_id,class_level,academic_year,changed_by) VALUES(?,?,?,?,?)');$classesImported=[];$imported=[];foreach($rows as $r){$insert->execute([$school,$r['admission_number'],$r['first_name'],$r['middle_name']?:null,$r['last_name'],$r['date_of_birth']?:null,$r['class_level'],$r['stream']?:null,$r['scholar_type'],$r['guardian_name']?:null,$r['guardian_phone']?:null]);$id=(int)$db->lastInsertId();$history->execute([$id,$school,$r['class_level'],(int)date('Y'),$uid]);$classesImported[$r['class_level']]=($classesImported[$r['class_level']]??0)+1;$imported[]=['id'=>$id,'admission_number'=>$r['admission_number'],'first_name'=>$r['first_name'],'middle_name'=>$r['middle_name'],'last_name'=>$r['last_name'],'class_level'=>$r['class_level'],'stream'=>$r['stream'],'scholar_type'=>$r['scholar_type'],'guardian_name'=>$r['guardian_name'],'guardian_phone'=>$r['guardian_phone']];}$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'bulk_register_pupils','pupil_import_batch',null,json_encode(['school_id'=>$school,'count'=>count($rows),'classes'=>$classesImported],JSON_THROW_ON_ERROR)]);$db->commit();pupil_import_json(200,['ok'=>true,'message'=>count($rows).' pupils imported.','data'=>['pupils'=>$imported,'classes'=>$classesImported]]);}catch(PDOException $e){if($db->inTransaction())$db->rollBack();if($e->getCode()==='23000')pupil_import_json(422,['ok'=>false,'message'=>'No pupils were imported because an admission number was added concurrently. Check the directory and upload again.']);error_log('Pupil CSV import database error: '.$e->getMessage());pupil_import_json(500,['ok'=>false,'message'=>'The import failed and no pupils were saved.']);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Pupil CSV import failed: '.$e->getMessage());pupil_import_json(500,['ok'=>false,'message'=>'The import failed and no pupils were saved.']);}
